export async function signIn<Fields extends SignInFields, MetadataFields extends ReadonlyArray<keyof SignInMetadata> = []>(
  config: {
  tenant: string;
  input: SignInInput;
  hookCtx?: ActionHookContext;
  fields: Fields;
  headers?: Record<string, string>;
  fetchOptions?: RequestInit;
  customFetch?: (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;
  metadataFields?: MetadataFields;
}
): Promise<SignInResult<Fields, MetadataFields>> {
  let processedConfig = config;
  if (RpcHooks.beforeRequest) {
    processedConfig = await RpcHooks.beforeRequest("sign_in", config);
  }

  const payload = {
    action: "sign_in",
    tenant: config.tenant,
    input: config.input,
    fields: config.fields,
    ...(config.metadataFields && { metadataFields: config.metadataFields })
  };

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...processedConfig.headers,
    ...config.headers,
  };

  const fetchFunction = config.customFetch || processedConfig.customFetch || fetch;
  const fetchOptions: RequestInit = {
    ...processedConfig.fetchOptions,
    ...config.fetchOptions,
    method: "POST",
    headers,
    body: JSON.stringify(payload),
  };

  const response = await fetchFunction("/rpc/run", fetchOptions);

  const result = response.ok ? await response.json() : null;

  if (RpcHooks.afterRequest) {
  await RpcHooks.afterRequest("sign_in", response, result, processedConfig);
}

  if (!response.ok) {
    return {
      success: false,
      errors: [{ type: "network", message: response.statusText, details: {} }],
    };
  }

  return result as SignInResult<Fields, MetadataFields>;
}


